/// Computes the inverse hyperbolic cosine (arccosh) of each element in the input vector.
/// 
/// For each x in the input, this returns ln(x + sqrt(x² - 1)), processed in order.
/// 
/// # Panics
/// 
/// Panics if any input value is less than 1.0 (since acosh is undefined for x < 1).
fn arccosh(x: Vec<f32>) -> Vec<f32> {
    // Pre‐allocate the output vector with the same length as the input.
    let n = x.len();
    let mut result = Vec::with_capacity(n);

    // Process each element by index from 0 to n-1.
    for i in 0..n {
        let xi = x[i];
        // acosh(x) = ln(x + sqrt(x² - 1))
        let yi = (xi + (xi * xi - 1.0).sqrt()).ln();
        result.push(yi);
    }

    result
}

