        let output = arccosh(input);
        // arccosh(1) = 0
        assert!((output[0] - 0.0).abs() < 1e-6);
        // arccosh(2) ≈ ln(2 + √3) ≈ 1.316957
        assert!((output[1] - 1.316957f32).abs() < 1e-6);
        // arccosh(1.5) ≈ ln(1.5 + √(1.5² - 1)) ≈ 0.962424
